(function(){
const $=id=>document.getElementById(id);let stats={},selected=null;
try{stats=JSON.parse(localStorage.getItem('plcquest.learning.v1'))||{};}catch{}
const box=document.createElement('div');box.className='learningtools';box.innerHTML=`<button id="reviewWeak" class="quiet">Practice weak spots</button><span id="reviewNote"></span>`;document.querySelector('.brief').after(box);
const details=document.createElement('details');details.className='diagnostics';details.innerHTML=`<summary>Live inputs, outputs, and wiring</summary><p class="helper">Tap a tag to find it in the ladder and highlight its input or output. Addresses below are illustrative training addresses.</p><div id="ioList" class="iolist"></div><div id="rungTrace" class="rungtrace" aria-live="polite">Use Step rung to follow one instruction row at a time.</div><details class="wiringlesson"><summary>Physical switch versus PLC bit</summary><p>A contact instruction reads a bit. A physical normally open or normally closed switch determines whether voltage reaches an input. They are separate choices.</p><label>Physical switch <select id="wireKind"><option value="no">Normally open</option><option value="nc">Normally closed</option></select></label><button id="wirePress" class="quiet" aria-pressed="false">Switch released</button><svg viewBox="0 0 420 105" role="img" aria-label="Training switch circuit"><text x="10" y="27">24 V</text><path id="wirePath" d="M20 55H155M220 55H340V80H20" fill="none" stroke-width="4"/><path id="wireContact" d="M155 55L215 30" fill="none" stroke-width="4"/><text x="280" y="28">PLC input I0.0</text><text x="10" y="101">0 V</text></svg><p id="wireResult"></p><p class="helper">Illustrative 24 VDC input circuit only. This does not represent a complete machine or safety circuit.</p></details>`;
 document.querySelector('.station').append(details);
const stepButton=document.createElement('button');stepButton.id='stepRung';stepButton.className='quiet';stepButton.textContent='Step rung';$('step').after(stepButton);stepButton.onclick=stepRung;
const speed=document.createElement('label');speed.className='speedcontrol';speed.innerHTML=`Speed <select id="lessonSpeed"><option value="0.25">¼ speed</option><option value="0.5">½ speed</option><option value="1" selected>Normal</option><option value="2">2×</option></select>`;document.querySelector('.simbar').append(speed);$('lessonSpeed').onchange=()=>setLessonSpeed(Number($('lessonSpeed').value));
const explanation=document.createElement('div');explanation.id='whyWorks';explanation.className='whyworks';explanation.hidden=true;$('feedback').after(explanation);
function save(){try{localStorage.setItem('plcquest.learning.v1',JSON.stringify(stats));}catch{}}
function source(){return randomLesson?.sourceId??(!randomLesson?index:null);}
function entry(){const id=source();if(id===null)return null;return stats[id]??=( {misses:0,hints:0,passes:0,unaided:0,last:0} );}
function condition(token){if(token==='EMPTY')return 'unfinished contact';if(token==='TRUE')return 'always true';if(/[<>=]/.test(token))return token;return (labels[token.replace('!','')]||token.replace('!',''))+' = '+(token.startsWith('!')?'0':'1');}
function explain(l,p){return l.rungs.map((r,i)=>{const when=r.groups.map(g=>g.length>1?'('+g.map(id=>condition(p[id])).join(' OR ')+')':condition(p[g[0]])).join(' AND ');const action={OTE:`${labels[r.out]||r.out} follows this condition each scan.`,OTL:`${labels[r.out]||r.out} is set and stays set when this condition later turns false.`,OTU:`${labels[r.out]||r.out} is cleared. Its later position gives it priority over an earlier latch.`,TON:`The ${p.preset}-second timer accumulates while true and resets when false.`,RTO:`The ${p.preset}-second timer retains elapsed time when false.`,CTU:`The counter increments on a false-to-true transition, with target ${p.preset}.`,RES:'The timer is reset to zero.'}[r.type];return `Rung ${i+1}: ${when}. ${action}`;});}
function result(ok,attempts){const e=entry();if(e){if(ok){e.passes++;if(attempts===0&&!e.currentHint)e.unaided++;e.last=Date.now();e.currentHint=false;}else e.misses++;save();}if(ok){$('whyWorks').hidden=false;$('whyWorks').innerHTML='<h3>Why this works</h3><ol>'+explain(currentLesson(),program).map(t=>'<li>'+esc(t)+'</li>').join('')+'</ol><p>The PLC evaluates these rungs from top to bottom every scan.</p>';}note();}
function note(){const weak=Object.entries(stats).filter(([id,e])=>LESSONS[id]&&(e.misses||e.hints)).length;$('reviewNote').textContent=weak?`${weak} concepts flagged for review. Unaided passes reduce their priority.`:'Review adapts as you use hints and retry lessons.';}
function refresh(){const l=currentLesson(),outs=[...new Set(l.rungs.map(r=>r.out).filter(x=>x&&x!=='TIMER'))],internals=l.rungs.some(r=>['TON','RTO','CTU'].includes(r.type))?['DONE','TIMING']:[];const rows=[...l.inputs.map((k,i)=>({k,value:inputs[k],address:'I0.'+i})),...outs.map((k,i)=>({k,value:state.bits[k],address:'Q0.'+i})),...internals.map(k=>({k,value:state.bits[k],address:'Internal'}))];$('ioList').innerHTML=rows.map(({k,value,address})=>`<button class="iotag ${selected===k?'selected':''}" data-tag="${k}"><span>${labels[k]||k}<small>${address} · ${k}</small></span><b>${typeof value==='number'?value:value?1:0}</b></button>`).join('');highlight();}
function highlight(){for(const el of document.querySelectorAll('[data-slot]'))el.classList.toggle('tagfocus',!!selected&&(program[el.dataset.slot]||'').replace('!','')===selected);for(const el of document.querySelectorAll('[data-coil]'))el.classList.toggle('tagfocus',el.dataset.coil===selected);for(const el of document.querySelectorAll('[data-input]'))el.classList.toggle('tagfocus',el.dataset.input===selected);for(const [id,t] of [['outMotor','MOTOR'],['outLamp','LAMP'],['outBelt2','BELT2'],['outLift','LIFT'],['sensorReadout','SENSOR']])$(id).classList.toggle('tagfocus',t===selected);$('sensorBeam').setAttribute('stroke-width',selected==='SENSOR'?'6':'2');}
function rung(i){for(const [n,el] of [...document.querySelectorAll('.rung')].entries())el.classList.toggle('activerung',n===i);const t=state.trace[i],r=currentLesson().rungs[i];$('rungTrace').textContent=`Rung ${i+1}: ${t.power?'TRUE':'FALSE'}. `+explain(currentLesson(),program)[i]+(partialScan?' Next press evaluates the following rung.':' Scan complete.');details.open=true;}
function reset(){selected=null;$('whyWorks').hidden=true;$('rungTrace').textContent='Use Step rung to follow one instruction row at a time.';for(const el of document.querySelectorAll('.activerung'))el.classList.remove('activerung');refresh();}
$('ioList').onclick=e=>{const b=e.target.closest('[data-tag]');if(b){selected=selected===b.dataset.tag?null:b.dataset.tag;refresh();}};
$('reviewWeak').onclick=()=>{const choices=LESSONS.map(l=>{const e=stats[l.id]||{};return {l,score:(e.misses||0)*2+(e.hints||0)*3-(e.unaided||0)*2+(e.last?Math.min(3,(Date.now()-e.last)/86400000):1)};}).sort((a,b)=>b.score-a.score);const l=choices[0].l;showMode('random');load(l.id,{...l,sourceId:l.id,title:'Review: '+l.title});};
let pressed=false;function wire(){const on=$('wireKind').value==='nc'?!pressed:pressed;$('wirePress').textContent=pressed?'Switch pressed':'Switch released';$('wirePress').setAttribute('aria-pressed',String(pressed));$('wirePath').setAttribute('stroke',on?'#326f68':'#78616a');$('wireContact').setAttribute('stroke',on?'#326f68':'#78616a');$('wireContact').setAttribute('d',on?'M155 55H220':'M155 55L215 30');$('wireResult').textContent=`Input bit = ${on?1:0}. XIC is ${on?'true':'false'}. XIO is ${on?'false':'true'}.`;}$('wirePress').onclick=()=>{pressed=!pressed;wire();};$('wireKind').onchange=wire;
window.Tutor={result,refresh,reset,rung,explain,hint:()=>{const e=entry();if(e){e.hints++;e.currentHint=true;save();note();}}};note();refresh();wire();
})();
